ALTER TABLE public.social_notifications ADD COLUMN message text, ADD COLUMN verification_request_id uuid REFERENCES public.verification_requests(id) ON DELETE SET NULL, ADD COLUMN verification_status text, ADD COLUMN verification_badge text;
ALTER TABLE public.social_notifications DROP CONSTRAINT social_notifications_kind_check;
ALTER TABLE public.social_notifications ADD CONSTRAINT social_notifications_kind_check CHECK(kind IN ('follow','request','like','comment','repost','verification'));
REVOKE UPDATE ON public.social_notifications FROM authenticated;
GRANT UPDATE(read_at) ON public.social_notifications TO authenticated;
CREATE OR REPLACE FUNCTION public.display_voice_badge(_user uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN public.is_main_admin(_user) THEN 'owner' ELSE (SELECT badge FROM public.voice_user_badges WHERE user_id=_user) END $$;
REVOKE ALL ON FUNCTION public.display_voice_badge(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.display_voice_badge(uuid) TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.social_profile(_username text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('id',p.id,'username',p.username,'display_name',p.display_name,'avatar_url',p.avatar_url,'bio',CASE WHEN public.can_view_social_profile(p.id) THEN p.bio ELSE NULL END,'is_public',p.is_public,'can_view',public.can_view_social_profile(p.id),'followers',(SELECT count(*) FROM profile_follows WHERE following_id=p.id),'following',(SELECT count(*) FROM profile_follows WHERE follower_id=p.id),'recordings',(SELECT count(*) FROM voice_recordings r WHERE r.host_id=p.id AND (r.is_public OR p.id=auth.uid())),'badge',public.display_voice_badge(p.id)) FROM profiles p WHERE lower(p.username)=lower(_username) OR p.id::text=_username LIMIT 1 $$;
CREATE OR REPLACE FUNCTION public.voice_people(_q text DEFAULT '',_admin boolean DEFAULT false) RETURNS TABLE(id uuid,username text,display_name text,avatar_url text,followers bigint,badge text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _admin AND NOT public.is_main_admin(auth.uid()) THEN RAISE EXCEPTION 'Owner access only'; END IF; RETURN QUERY SELECT p.id,p.username,p.display_name,p.avatar_url,(SELECT count(*) FROM profile_follows f WHERE f.following_id=p.id),public.display_voice_badge(p.id) FROM profiles p WHERE p.username IS NOT NULL AND (trim(coalesce(_q,''))='' OR p.username ILIKE '%'||left(trim(_q),100)||'%' OR p.display_name ILIKE '%'||left(trim(_q),100)||'%') ORDER BY CASE public.display_voice_badge(p.id) WHEN 'owner' THEN 0 WHEN 'golden' THEN 1 WHEN 'verified' THEN 2 ELSE 3 END,5 DESC,p.id LIMIT CASE WHEN trim(coalesce(_q,''))='' AND NOT _admin THEN 5 ELSE 40 END; END $$;
CREATE OR REPLACE FUNCTION public.review_verification(_request uuid,_badge text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; BEGIN IF NOT public.is_main_admin(auth.uid()) THEN RAISE EXCEPTION 'Owner access only'; END IF; IF _badge IS NOT NULL AND _badge NOT IN ('verified','golden') THEN RAISE EXCEPTION 'Invalid verification badge'; END IF; SELECT user_id INTO target FROM verification_requests WHERE id=_request AND status='pending' FOR UPDATE; IF target IS NULL THEN RAISE EXCEPTION 'Pending request not found'; END IF; IF _badge IS NOT NULL THEN INSERT INTO voice_user_badges(user_id,badge) VALUES(target,_badge) ON CONFLICT(user_id) DO UPDATE SET badge=excluded.badge,updated_at=now(); END IF; UPDATE verification_requests SET status=CASE WHEN _badge IS NULL THEN 'rejected' ELSE 'approved' END WHERE id=_request; END $$;
CREATE OR REPLACE FUNCTION public.reply_verification(_request uuid,_message text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE req public.verification_requests; notification uuid; BEGIN IF NOT public.is_main_admin(auth.uid()) THEN RAISE EXCEPTION 'Owner access only'; END IF; IF _message IS NULL OR length(trim(_message)) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Reply must contain 1 to 2000 characters'; END IF; SELECT * INTO req FROM verification_requests WHERE id=_request FOR UPDATE; IF NOT FOUND OR req.status NOT IN ('approved','rejected') THEN RAISE EXCEPTION 'Review the request before replying'; END IF; INSERT INTO social_notifications(recipient_id,actor_id,kind,message,verification_request_id,verification_status,verification_badge) VALUES(req.user_id,auth.uid(),'verification',trim(_message),req.id,req.status,CASE WHEN req.status='approved' THEN public.display_voice_badge(req.user_id) ELSE NULL END) RETURNING id INTO notification; RETURN notification; END $$;
REVOKE ALL ON FUNCTION public.review_verification(uuid,text),public.reply_verification(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.review_verification(uuid,text),public.reply_verification(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_verification_request() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' AND NEW.status IS DISTINCT FROM 'pending' THEN RAISE EXCEPTION 'New verification requests must be pending'; END IF; IF TG_OP='UPDATE' AND NOT public.is_main_admin(auth.uid()) THEN RAISE EXCEPTION 'Owner access only'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_verification_request BEFORE INSERT OR UPDATE ON public.verification_requests FOR EACH ROW EXECUTE FUNCTION public.guard_verification_request();